"use strict";(self.webpackChunkbodylapse_docs=self.webpackChunkbodylapse_docs||[]).push([[5553],{5322(e){e.exports=JSON.parse('{"tag":{"label":"content","permalink":"/bodylapse-docs/features/tags/content","allTagsPath":"/bodylapse-docs/features/tags","count":7,"items":[{"id":"daily-calorie-target","title":"Daily calorie target","description":"The recommended daily intake, computed on read from the profile with Mifflin-St Jeor, an activity multiplier and a bounded pace, with its safety rules and the screens that show it.","permalink":"/bodylapse-docs/features/daily-calorie-target"},{"id":"goals","title":"Goals","description":"The goal direction (Lose, Gain or Maintain) and its pace, how they are stored with a history of changes, and where the user sets them.","permalink":"/bodylapse-docs/features/goals"},{"id":"onboarding","title":"Onboarding","description":"The ten-step first-run flow that sets the goal, the details and activity behind the calorie target, the pace, the pose-guide body type, camera and reminder permissions, and offers the first check-in.","permalink":"/bodylapse-docs/features/onboarding"},{"id":"palettes-and-appearance","title":"Palettes and appearance","description":"Six colour palettes and an Auto, Light or Dark appearance, chosen in Settings and synced; colours are written once in Plum and mapped through a generated table, and the camera always uses Night values.","permalink":"/bodylapse-docs/features/palettes-and-appearance"},{"id":"photo-check-ins","title":"Photo check-ins","description":"The guided camera flow that captures a set of consistent progress photos, propped hands-free or in a mirror, processes each photo in the background and saves them as a check-in.","permalink":"/bodylapse-docs/features/photo-check-ins"},{"id":"compare","title":"Progress and compare","description":"The Progress tab\'s grid of check-ins, each check-in\'s detail with share, merge and delete, and Compare, which shows two check-ins side by side or under a slider, lined up by shoulders and hips.","permalink":"/bodylapse-docs/features/compare"},{"id":"reminders","title":"Reminders","description":"The check-in reminder, a local notification on a chosen cadence, weekday and time, plus Today\'s due state and the one-off \\"Remind me in an hour\\".","permalink":"/bodylapse-docs/features/reminders"}],"unlisted":false}}')}}]);